function parseLabel(output, allowed) {
  const lines = output.split("\n").map((l) => l.trim()).filter(Boolean);
  if (!lines.length) return "unknown";
  let last = lines[lines.length - 1].replace(/^label:\s*/i, "").replace(/\.$/, "").trim().toLowerCase();
  const hit = allowed.find((a) => a.toLowerCase() === last);
  return hit ?? "unknown";
}

def majority_vote(answers):
    norm = [a.strip().lower() for a in answers]
    if not norm:
        return None
    best = None
    for a in norm:
        if best is None or norm.count(a) > norm.count(best):
            best = a
    return best

