coding.referenceSolution:
function passRate(outputs, expected) {
  if (!outputs.length) return 0;
  const norm = (s) => String(s).trim().toLowerCase();
  let pass = 0;
  outputs.forEach((o, i) => { if (norm(o) === norm(expected[i])) pass++; });
  return Math.round((pass / outputs.length) * 100) / 100;
}

